async function buildLeaveEmbed(l) {
    const st = l.status;
    const color = st === "approved" ? 0x16a34a : st === "rejected" ? 0xef4444 : st === "completed" ? 0x6b7280 : 0xf59e0b;
    const title = st === "approved" ? "✅ تمت الموافقة على الإجازة" : st === "rejected" ? "❌ تم رفض طلب الإجازة" : st === "completed" ? "🏁 انتهت الإجازة" : "🌴 طلب إجازة جديد";
    const p = await Personnel.findOne({ discord: l.discord }, { leaveBalance: 1 }).lean();
    const balance = p ? (p.leaveBalance ?? CONFIG.DEFAULT_LEAVE_BALANCE) : CONFIG.DEFAULT_LEAVE_BALANCE;
    const embed = new EmbedBuilder()
        .setTitle(title)
        .setColor(color)
        .addFields(
            { name: "العسكري", value: (l.name || l.discordTag || "-") + (l.discord ? "\n<@" + l.discord + ">" : ""), inline: true },
            { name: "الرتبة / الوحدة", value: (l.rank || "-") + " · " + (l.unit || "-"), inline: true },
            { name: "القطاع", value: l.sectorLabel || "-", inline: true },
            { name: "مدة الإجازة", value: l.days + " يوم", inline: true },
            { name: "الرصيد الحالي", value: balance + " يوم", inline: true },
            { name: "السبب", value: (l.reason || "-").slice(0, 1000), inline: false },
        )
        .setFooter({ text: "ID: " + l._id })
        .setTimestamp(l.createdAt || new Date());
    if (st !== "pending" && l.reviewedByTag) embed.addFields({ name: "القرار بواسطة", value: l.reviewedByTag, inline: false });
    return embed;
}

function buildLeaveButtons(l) {
    return new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId("leave_ok_" + l._id).setLabel("✅ قبول").setStyle(ButtonStyle.Success),
        new ButtonBuilder().setCustomId("leave_no_" + l._id).setLabel("❌ رفض").setStyle(ButtonStyle.Danger),
    );
}

async function postLeaveRequest(l) {
    if (!botReady) return;
    try {
        const channel = await client.channels.fetch(CONFIG.LEAVE_CHANNEL_ID);
        const msg = await channel.send({ embeds: [await buildLeaveEmbed(l)], components: [buildLeaveButtons(l)] });
        await LeaveRequest.updateOne({ _id: l._id }, { $set: { channelId: msg.channelId, messageId: msg.id } });
    } catch (e) {
        console.error("❌ فشل إرسال طلب الإجازة للديسكورد:", e.message);
    }
}

async function refreshLeaveMessage(l) {
    if (!botReady || !l || !l.channelId || !l.messageId) return;
    try {
        const channel = await client.channels.fetch(l.channelId);
        const msg = await channel.messages.fetch(l.messageId);
        await msg.edit({ embeds: [await buildLeaveEmbed(l)], components: l.status === "pending" ? [buildLeaveButtons(l)] : [] });
    } catch (e) {
        console.error("❌ فشل تحديث رسالة الإجازة:", e.message);
    }
}

async function decideLeaveRequest(id, userId, userTag, decision, member) {
    try {
        if (!mongoose.Types.ObjectId.isValid(id)) return { error: "الطلب غير موجود" };
        const settings = await getSettings();
        const leave = await LeaveRequest.findById(id);
        if (!leave || leave.status !== "pending") return { error: "هذا الطلب تمت مراجعته مسبقاً" };
        const leaderInfo = getSectorRole(userId, settings);
        const poInfo = getPersonnelOfficerSector(userId, settings);
        let approverLabel = null;
        if (leaderInfo && leaderInfo.sector === leave.sector) approverLabel = leaderInfo.role === "commander" ? "قائد القطاع" : "نائب القطاع";
        else if (poInfo && poInfo.sector === leave.sector && inPoScope(poInfo, leave.rank)) approverLabel = poInfo.kind === "oo" ? "مسؤول الضباط" : "مسؤول الأفراد";
        else if (isSeniorAdmin(userId)) approverLabel = "كبار المسؤولين";
        else if (CONFIG.LEAVE_REVIEWER_ROLE_ID && member && member.roles && member.roles.cache && member.roles.cache.has(CONFIG.LEAVE_REVIEWER_ROLE_ID)) approverLabel = "مسؤول الإجازات";
        else return { error: "ما عندك صلاحية على هذا الطلب" };
        const tag = userTag + " (" + approverLabel + ")";
        const now = new Date();
        if (decision === "reject") {
            const r = await LeaveRequest.findOneAndUpdate(
                { _id: id, status: "pending" },
                { $set: { status: "rejected", rejectReason: null, reviewedBy: userId, reviewedByTag: tag, reviewedAt: now } },
                { new: true }
            );
            if (!r) return { error: "هذا الطلب تمت مراجعته مسبقاً" };
            await logEvent({ action: "رفض إجازة", discordId: r.discord, discordTag: r.discordTag, actorId: userId, actorTag: userTag, details: "من الديسكورد" });
            await refreshLeaveMessage(r);
            return { ok: true };
        }
        const p = await Personnel.findOne({ discord: leave.discord });
        if (!p) return { error: "الفرد غير موجود" };
        const balance = p.leaveBalance ?? CONFIG.DEFAULT_LEAVE_BALANCE;
        if (leave.days > balance) return { error: "رصيد الفرد الحالي ما يكفي لهذا الطلب" };
        const r = await LeaveRequest.findOneAndUpdate(
            { _id: id, status: "pending" },
            { $set: { status: "approved", deductMode: "days", reviewedBy: userId, reviewedByTag: tag, reviewedAt: now, startDate: now, endDate: new Date(now.getTime() + leave.days * 24 * 60 * 60 * 1000) } },
            { new: true }
        );
        if (!r) return { error: "هذا الطلب تمت مراجعته مسبقاً" };
        const wasOut = await attForceOut(leave.discord, "system:leave").catch(() => false);
        await logEvent({ action: "قبول إجازة", discordId: p.discord, discordTag: p.discordTag, actorId: userId, actorTag: userTag, details: `${leave.days} يوم (بواسطة ${approverLabel} من الديسكورد) — الخصم يتم عند انتهاء الإجازة بالأيام الفعلية${wasOut ? " — انسجّل انصرافه تلقائياً" : ""}` });
        await refreshLeaveMessage(r);
        return { ok: true };
    } catch (e) {
        console.error("❌ خطأ بقرار الإجازة:", e.message);
        return { error: "صار خطأ، حاول مرة ثانية" };
    }
}

app.get("/api/leave/mine", ensureAuth, async (req, res) => {
    const p = await Personnel.findOne({ discord: req.user.id }, { leaveBalance: 1 });
    const list = await LeaveRequest.find({ discord: req.user.id }).sort({ createdAt: -1 }).limit(50).lean();
    res.json({ balance: p ? (p.leaveBalance ?? CONFIG.DEFAULT_LEAVE_BALANCE) : CONFIG.DEFAULT_LEAVE_BALANCE, list });
});

app.post("/api/leave/request", ensureAuth, async (req, res) => {
    const { reason, days } = req.body;
    const d = parseInt(days);
    if (!reason || !reason.trim()) return res.status(400).json({ error: "لازم تكتب السبب" });
    if (!d || d < 1) return res.status(400).json({ error: "حدد عدد أيام صحيح" });

    const p = await Personnel.findOne({ discord: req.user.id });
    if (!p || !p.registeredName) return res.status(400).json({ error: "أكمل بياناتك بالموقع أولاً" });
    if (isSummonBlocking(p)) return res.status(403).json({ error: "🚨 عليك استدعاء نشط من الشؤون العسكرية، لازم تدخل الاستدعاء أولاً قبل أي إجراء بالموقع" });
    const balance = p.leaveBalance ?? CONFIG.DEFAULT_LEAVE_BALANCE;
    if (d > balance) return res.status(400).json({ error: `رصيدك الحالي ${balance} يوم فقط، ما يكفي لهذا الطلب` });

    const pending = await LeaveRequest.countDocuments({ discord: req.user.id, status: "pending" });
    if (pending >= 2) return res.status(400).json({ error: "عندك طلب إجازة قيد المراجعة بالفعل" });

    const active = await LeaveRequest.findOne({ discord: req.user.id, status: "approved" });
    if (active) return res.status(400).json({ error: "عندك إجازة نشطة حالياً، ما تقدر تطلب إجازة جديدة إلا بعد ما تنتهي" });

    const lastCompleted = await LeaveRequest.findOne({ discord: req.user.id, status: "completed" }).sort({ endedAt: -1 });
    if (lastCompleted && lastCompleted.endedAt) {
        const cooldownMs = 3 * 24 * 60 * 60 * 1000;
        const sinceEnd = Date.now() - new Date(lastCompleted.endedAt).getTime();
        if (sinceEnd < cooldownMs) {
            const daysLeft = Math.ceil((cooldownMs - sinceEnd) / (24 * 60 * 60 * 1000));
            return res.status(400).json({ error: `لازم تنتظر ${daysLeft} يوم إضافي بعد انتهاء آخر إجازة قبل تقديم طلب جديد` });
        }
    }

    const sectorKey = await getMemberSectorKey(req.user.id);
    const leave = await LeaveRequest.create({
        discord: req.user.id, discordTag: req.user.username,
        name: p.registeredName, unit: p.unit, rank: p.rank,
        sector: sectorKey, sectorLabel: sectorKey ? CONFIG.SECTORS[sectorKey] : null,
        reason: reason.trim(), days: d,
    });
    await logEvent({ action: "طلب إجازة", discordId: p.discord, discordTag: p.discordTag, actorId: p.discord, actorTag: p.discordTag, details: `${d} يوم — ${reason.trim()}` });
    await postLeaveRequest(leave);
    res.json({ ok: true, leave });
});

app.get("/api/leave/pending", ensureAuth, async (req, res) => {
    const settings = await getSettings();
    const leaderInfo = getSectorRole(req.user.id, settings);
    const poInfo = getPersonnelOfficerSector(req.user.id, settings);
    if (!leaderInfo && !poInfo && !isSeniorAdmin(req.user.id)) return res.status(403).json({ error: "ليست لديك صلاحية" });

    let query = { status: { $in: ["pending", "approved", "rejected", "completed"] } };
    if (isSeniorAdmin(req.user.id) && !leaderInfo && !poInfo) {
        const q = (req.query.sector || "").trim();
        if (!q || !CONFIG.SECTORS[q]) return res.status(400).json({ error: "حدد قطاع صحيح" });
        query.sector = q;
    } else if (leaderInfo) {
        query.sector = leaderInfo.sector;
    } else if (poInfo) {
        query.sector = poInfo.sector;
    }

    let list = await LeaveRequest.find(query).sort({ createdAt: -1 }).limit(100).lean();
    if (poInfo && !leaderInfo) {
        list = list.filter(l => inPoScope(poInfo, l.rank));
    }
    res.json({ list });
});

app.get("/api/senior/leave/pending", ensureSeniorAdmin, async (req, res) => {
    const list = await LeaveRequest.find({ status: { $in: ["pending", "approved", "rejected", "completed"] } }).sort({ createdAt: -1 }).limit(200).lean();
    res.json({ list });
});

app.post("/api/leave/:id/approve", ensureAuth, async (req, res) => {
    const settings = await getSettings();
    const leave = await LeaveRequest.findById(req.params.id);
    if (!leave || leave.status !== "pending") return res.status(404).json({ error: "غير موجود" });

    const leaderInfo = getSectorRole(req.user.id, settings);
    const poInfo = getPersonnelOfficerSector(req.user.id, settings);
    let approverLabel = null;
    if (leaderInfo && leaderInfo.sector === leave.sector) {
        approverLabel = leaderInfo.role === "commander" ? "قائد القطاع" : "نائب القطاع";
    } else if (poInfo && poInfo.sector === leave.sector && inPoScope(poInfo, leave.rank)) {
        approverLabel = poInfo.kind === "oo" ? "مسؤول الضباط" : "مسؤول الأفراد";
    } else if (isSeniorAdmin(req.user.id)) {
        approverLabel = "كبار المسؤولين";
    } else {
        return res.status(403).json({ error: "ليست لديك صلاحية الموافقة على هذا الطلب" });
    }

    const p = await Personnel.findOne({ discord: leave.discord });
    if (!p) return res.status(404).json({ error: "الفرد غير موجود" });
    const balance = p.leaveBalance ?? CONFIG.DEFAULT_LEAVE_BALANCE;
    if (leave.days > balance) return res.status(400).json({ error: "رصيد الفرد الحالي ما يكفي لهذا الطلب" });

    leave.status = "approved";
    leave.deductMode = "days";
    leave.reviewedBy = req.user.id;
    leave.reviewedByTag = req.user.username + ` (${approverLabel})`;
    leave.reviewedAt = new Date();
    leave.startDate = new Date();
    leave.endDate = new Date(Date.now() + leave.days * 24 * 60 * 60 * 1000);
    await leave.save();

    const wasOut = await attForceOut(leave.discord, "system:leave").catch(() => false);
    await logEvent({ action: "قبول إجازة", discordId: p.discord, discordTag: p.discordTag, actorId: req.user.id, actorTag: req.user.username, details: `${leave.days} يوم (بواسطة ${approverLabel}) — الخصم يتم عند انتهاء الإجازة بالأيام الفعلية${wasOut ? " — انسجّل انصرافه تلقائياً" : ""}` });
    await refreshLeaveMessage(leave);
    res.json({ ok: true, leave });
});

app.post("/api/leave/:id/end", ensureAuth, async (req, res) => {
    const settings = await getSettings();
    const leave = await LeaveRequest.findById(req.params.id);
    if (!leave || leave.status !== "approved") return res.status(404).json({ error: "غير موجودة أو مو نشطة" });

    const leaderInfo = getSectorRole(req.user.id, settings);
    const poInfo = getPersonnelOfficerSector(req.user.id, settings);
    let approverLabel = null;
    if (leaderInfo && leaderInfo.sector === leave.sector) approverLabel = leaderInfo.role === "commander" ? "قائد القطاع" : "نائب القطاع";
    else if (poInfo && poInfo.sector === leave.sector && inPoScope(poInfo, leave.rank)) approverLabel = poInfo.kind === "oo" ? "مسؤول الضباط" : "مسؤول الأفراد";
    else if (isSeniorAdmin(req.user.id)) approverLabel = "كبار المسؤولين";
    else return res.status(403).json({ error: "ليست لديك صلاحية إنهاء هذه الإجازة" });

    const done = await finalizeLeave(leave, req.user.username + ` (${approverLabel})`);
    if (!done) return res.status(404).json({ error: "غير موجودة أو مو نشطة" });
    res.json({ ok: true, usedDays: done.usedDays });
});

app.delete("/api/leave/:id", ensureAuth, async (req, res) => {
    const settings = await getSettings();
    const leave = await LeaveRequest.findById(req.params.id);
    if (!leave) return res.status(404).json({ error: "غير موجود" });
    if (leave.status !== "rejected" && leave.status !== "completed") return res.status(400).json({ error: "تقدر تحذف المرفوضة والمنتهية فقط" });

    const leaderInfo = getSectorRole(req.user.id, settings);
    const poInfo = getPersonnelOfficerSector(req.user.id, settings);
    let approverLabel = null;
    if (leaderInfo && leaderInfo.sector === leave.sector) approverLabel = leaderInfo.role === "commander" ? "قائد القطاع" : "نائب القطاع";
    else if (poInfo && poInfo.sector === leave.sector && inPoScope(poInfo, leave.rank)) approverLabel = poInfo.kind === "oo" ? "مسؤول الضباط" : "مسؤول الأفراد";
    else if (isSeniorAdmin(req.user.id)) approverLabel = "كبار المسؤولين";
    else return res.status(403).json({ error: "ليست لديك صلاحية" });

    // الرصيد يرجع: المرفوضة ما انخصم منها شي، والمنتهية يرجع اللي انخصم منها
    const refund = leave.status === "completed" ? (leave.usedDays ?? leave.days) : 0;
    const del = await LeaveRequest.findOneAndDelete({ _id: leave._id, status: leave.status });
    if (!del) return res.status(404).json({ error: "غير موجود" });
    if (refund > 0) {
        const p = await Personnel.findOne({ discord: leave.discord });
        if (p) await Personnel.updateOne({ discord: leave.discord }, { $set: { leaveBalance: (p.leaveBalance ?? CONFIG.DEFAULT_LEAVE_BALANCE) + refund } });
    }
    await logEvent({ action: "حذف إجازة", discordId: leave.discord, discordTag: leave.discordTag, actorId: req.user.id, actorTag: req.user.username, details: `${leave.status === "rejected" ? "مرفوضة" : "منتهية"} — بواسطة ${approverLabel}${refund ? " — رجع للرصيد " + refund + " يوم" : ""}` });
    if (leave.channelId && leave.messageId && botReady) {
        try { const ch = await client.channels.fetch(leave.channelId); const m = await ch.messages.fetch(leave.messageId); await m.delete(); } catch (e) {}
    }
    res.json({ ok: true, refunded: refund });
});

app.post("/api/leave/:id/reject", ensureAuth, async (req, res) => {
    const settings = await getSettings();
    const leave = await LeaveRequest.findById(req.params.id);
    if (!leave || leave.status !== "pending") return res.status(404).json({ error: "غير موجود" });

    const leaderInfo = getSectorRole(req.user.id, settings);
    const poInfo = getPersonnelOfficerSector(req.user.id, settings);
    let approverLabel = null;
    if (leaderInfo && leaderInfo.sector === leave.sector) approverLabel = leaderInfo.role === "commander" ? "قائد القطاع" : "نائب القطاع";
    else if (poInfo && poInfo.sector === leave.sector && inPoScope(poInfo, leave.rank)) approverLabel = poInfo.kind === "oo" ? "مسؤول الضباط" : "مسؤول الأفراد";
    else if (isSeniorAdmin(req.user.id)) approverLabel = "كبار المسؤولين";
    else return res.status(403).json({ error: "ليست لديك صلاحية" });

    leave.status = "rejected";
    leave.rejectReason = (req.body.reason || "").trim() || null;
    leave.reviewedBy = req.user.id;
    leave.reviewedByTag = req.user.username + ` (${approverLabel})`;
    leave.reviewedAt = new Date();
    await leave.save();

    await logEvent({ action: "رفض إجازة", discordId: leave.discord, discordTag: leave.discordTag, actorId: req.user.id, actorTag: req.user.username, details: leave.rejectReason || "-" });
    await refreshLeaveMessage(leave);
    res.json({ ok: true, leave });
});

