    await SupportTicket.deleteOne({ _id: t._id, status: "closed" });
    await logEvent({ action: "حذف تكت دعم", actorId: req.user.id, actorTag: req.user.username, details: "#" + t.no + " — " + (t.name || "-") });
    res.json({ ok: true });
