app.get("/api/cyber/cases/:id/room", ensureAuth, async (req, res) => {
    const x = await cyAccess(req, res, false); if (!x) return;
    const c = x.c;
    const settings = await getSettings();
    const sl = (settings.sectorLeadership || {}).cyber || {};
    const leaderIds = [sl.commanderId, sl.deputyId].filter(Boolean);
    const memberDocs = await Account.find({ status: "approved", sector: "cyber" }, { uid: 1 }).lean();
    const roleOf = new Map();
    memberDocs.forEach(m => roleOf.set(m.uid, "member"));
    leaderIds.forEach(u => roleOf.set(u, "leader"));
    roleOf.set(c.targetUid, "target");
    if (x.role.isLeader) roleOf.set(req.user.id, roleOf.get(req.user.id) === "target" ? "target" : "leader");
    const uids = Array.from(roleOf.keys());
    const names = new Map();
    (await Personnel.find({ discord: { $in: uids } }, { discord: 1, registeredName: 1 }).lean()).forEach(p => { if (p.registeredName) names.set(p.discord, p.registeredName); });
    (await Account.find({ uid: { $in: uids } }, { uid: 1, fullName: 1, email: 1 }).lean()).forEach(a => { if (!names.has(a.uid)) names.set(a.uid, a.fullName || a.email); });
    const online = new Set();
    for (const cl of sseClients) if (cl.uid) online.add(cl.uid);
    const order = { target: 0, leader: 1, member: 2 };
    const participants = uids.map(u => ({ uid: u, name: names.get(u) || u, role: roleOf.get(u), online: online.has(u) })).sort((a, b) => order[a.role] - order[b.role]);
    const meRole = x.isTarget ? "target" : (x.role.isLeader ? "leader" : "member");
    res.json({
        c: Object.assign(cyPublic(c), { shown: c.shown || null }), me: { uid: req.user.id, role: meRole }, participants, muted: c.muted || [], kicked: c.kicked || [],
        messages: (c.chat || []).slice(-200).map(m => ({ uid: m.uid, name: m.name, role: m.role, text: m.text, system: !!m.system, at: m.at })),
    });
});
app.post("/api/cyber/cases/:id/chat", ensureAuth, async (req, res) => {
    const x = await cyAccess(req, res, false); if (!x) return;
    if (x.c.status !== "investigating") return res.status(400).json({ error: "التحقيق منتهي" });
    if ((x.c.muted || []).includes(req.user.id)) return res.status(403).json({ error: "🔇 تم إسكاتك في هذا التحقيق" });
    const text = String((req.body && req.body.text) || "").trim().slice(0, 500);
    if (!text) return res.status(400).json({ error: "اكتب رسالة" });
    const role = x.isTarget ? "target" : (x.role.isLeader ? "leader" : "member");
    const name = await cyName(req.user.id);
    const mid = cyMid();
    await CyberCase.updateOne({ _id: x.c._id, status: "investigating" }, { $push: { chat: { $each: [{ uid: req.user.id, name, role, text, mid }], $slice: -500 } } });
    const vm = x.c.voiceN ? offLive.get(x.c.voiceN) : null;
    if (vm) { const msg = { id: mid, uid: req.user.id, name, isSenior: role === "leader", text, at: Date.now() }; for (const u of Array.from(vm.keys())) offSendTo(u, { t: "chat", n: x.c.voiceN, msg }); }
    cyberPush(x.c);
    res.json({ ok: true });
});
app.post("/api/cyber/cases/:id/mute", ensureAuth, async (req, res) => {
    const x = await cyAccess(req, res, false); if (!x) return;
    if (x.c.status !== "investigating") return res.status(400).json({ error: "التحقيق منتهي" });
    const target = String((req.body && req.body.uid) || "");
    const on = !!(req.body && req.body.on);
    if (!target) return res.status(400).json({ error: "حدد الشخص" });
    const allowed = x.isTarget ? false : (x.role.isLeader ? target !== req.user.id : (x.role.isMember && target === x.c.targetUid));
    if (!allowed) return res.status(403).json({ error: x.role.isMember ? "عضو القطاع يقدر يسكّت المتحقق معه فقط" : "ليست لديك صلاحية" });
    const name = await cyName(req.user.id);
    const tName = await cyName(target);
    await CyberCase.updateOne({ _id: x.c._id }, on ? { $addToSet: { muted: target } } : { $pull: { muted: target } });
    const vmm = x.c.voiceN ? offLive.get(x.c.voiceN) : null;
    if (vmm && vmm.has(target)) { vmm.get(target).muted = on; offPushState(x.c.voiceN); }
    await cySystemMsg(x.c._id, on ? `🔇 ${name} أسكت ${tName}` : `🔊 ${name} فك الإسكات عن ${tName}`);
    cyberPush(x.c);
    res.json({ ok: true });
});

const CY_DAY = 86400000;
async function cyGuard(req, res) {
    const uid = req.user.id;
    if (underInvestigation.has(uid)) { res.status(403).json({ error: "🔒 حسابك تحت التحقيق السيبراني" }); return null; }
    const role = await cyberRoleOf(uid);
    if (!role.isMember && !role.isLeader) { res.status(403).json({ error: "هذا القسم لقطاع الأمن السيبراني فقط" }); return null; }
    return role;
}
function cyIsProtected(uid, acc) {
    return !!(isSeniorAdmin(uid) || isOwnerUid(uid) || (acc && (acc.isSenior || acc.isOwner || acc.tempSenior)));
}
async function cyMemberInfo(accs) {
    const uids = accs.map(a => a.uid);
    const pers = await Personnel.aggregate([
        { $match: { discord: { $in: uids } } },
        { $project: { discord: 1, discordTag: 1, registeredName: 1, isBlocked: 1, isDismissed: 1 } },
    ]).option({ maxTimeMS: 10000 });
    const pmap = new Map(pers.map(p => [p.discord, p]));
    const logins = await DeviceSession.aggregate([
        { $match: { uid: { $in: uids } } },
        { $sort: { loginAt: -1 } },
        { $group: { _id: "$uid", last: { $first: "$loginAt" }, lastIp: { $first: "$ip" }, ips: { $addToSet: { $cond: [{ $gte: ["$loginAt", new Date(Date.now() - 7 * CY_DAY)] }, "$ip", null] } }, uas: { $addToSet: { $cond: [{ $gte: ["$loginAt", new Date(Date.now() - 7 * CY_DAY)] }, "$ua", null] } } } },
    ]).allowDiskUse(true).option({ maxTimeMS: 10000 });
    const lmap = new Map(logins.map(l => [l._id, l]));
    const online = new Set();
    for (const cl of sseClients) if (cl.uid) online.add(cl.uid);
    return accs.map(a => {
        const p = pmap.get(a.uid) || {};
        const l = lmap.get(a.uid) || {};
        const ips = (l.ips || []).filter(Boolean);
        const devs = new Set((l.uas || []).filter(Boolean).map(cyUaLabel));
        return {
            uid: a.uid,
            name: p.registeredName || a.fullName || a.uid,
            age: a.age || null,
            nationality: a.nationality || null,
            discordTag: p.discordTag || null,
            joinedAt: a.createdAt || null,
            lastLogin: l.last || null,
            lastIp: l.lastIp || null,
            ipCount: ips.length,
            deviceCount: devs.size,
            blocked: !!(p.isBlocked || p.isDismissed),
            online: online.has(a.uid),
            investigated: underInvestigation.has(a.uid),
            isSenior: cyIsProtected(a.uid, a),
        };
    });
}
function cyUaLabel(ua) {
    ua = String(ua || "");
    let os = "جهاز";
    if (/iPhone|iPad|iPod/i.test(ua)) os = "آيفون/آيباد";
    else if (/Android/i.test(ua)) os = "أندرويد";
    else if (/Windows/i.test(ua)) os = "ويندوز";
    else if (/Macintosh|Mac OS/i.test(ua)) os = "ماك";
    else if (/Linux/i.test(ua)) os = "لينكس";
    let br = "";
    if (/Edg\//i.test(ua)) br = "Edge";
    else if (/OPR\/|Opera/i.test(ua)) br = "Opera";
    else if (/Firefox/i.test(ua)) br = "Firefox";
    else if (/Chrome|CriOS/i.test(ua)) br = "Chrome";
    else if (/Safari/i.test(ua)) br = "Safari";
    return br ? os + " — " + br : os;
}
// العمليات اللي تظهر للأمن السيبراني: نشاط العضو داخل الموقع نفسه (دخول/أجهزة/حسابات/إعدادات) — بدون أي شي عسكري
const CY_OP_ACTIONS = ["تعديل إعدادات الموقع", "تعديل حساب", "قبول حساب جديد", "رفض حساب جديد", "طلب تسجيل جديد", "حذف حساب نهائي", "إنشاء حساب كبير مسؤولين جديد", "حظر من الدعم الفني", "فك حظر من الدعم الفني", "حذف اللوق الشامل", "إضافة عضو للقيادة العليا", "إزالة عضو من القيادة العليا", "حذف التكتات المغلقة", "حذف تكت دعم", "نشر تحديث جديد بفلاش"];
async function cyOpsOf(uid, from, to) {
    let t1 = (to instanceof Date && !isNaN(+to)) ? to : new Date();
    let t0 = (from instanceof Date && !isNaN(+from)) ? from : new Date(+t1 - CY_DAY);
    if (t0 > t1) { const x = t0; t0 = t1; t1 = x; }
    if (t1 - t0 > 90 * CY_DAY) t0 = new Date(+t1 - 90 * CY_DAY);
    const range = { $gte: t0, $lte: t1 };
    const logs = await Log.find({ actorId: uid, createdAt: range, $or: [{ action: { $in: CY_OP_ACTIONS } }, { action: /سيبراني/ }] }).sort({ createdAt: -1 }).limit(100).maxTimeMS(8000).lean();
    const sess = await DeviceSession.find({ uid, loginAt: range }, { ip: 1, ua: 1, loginAt: 1 }).sort({ loginAt: -1 }).limit(100).maxTimeMS(8000).lean();
    const flags = await CyberFlag.find({ targetUid: uid, kind: { $in: CY_FLAG_KINDS }, $or: [{ lastAt: range }, { createdAt: range }] }).sort({ lastAt: -1 }).limit(100).maxTimeMS(8000).lean();
    const devs = await CyberCase.find({ targetUid: uid, kind: { $ne: "manual" }, createdAt: range }, { targetName: 1, relatedName: 1, createdAt: 1 }).sort({ createdAt: -1 }).limit(100).maxTimeMS(8000).lean();
    const vios = await Violation.find({ reporterDiscord: uid, createdAt: range }, { violationType: 1, kind: 1, reportCategory: 1, status: 1, createdAt: 1 }).sort({ createdAt: -1 }).limit(100).maxTimeMS(8000).lean();
    const out = [];
    const VST = { pending: "قيد المراجعة", approved: "مقبولة", rejected: "مرفوضة" };
    vios.forEach(v => out.push({ id: "vio:" + v._id, kind: "vio", title: v.kind === "report" ? "تسجيل تقرير مكافحة مخدرات" : "تسجيل مخالفة", details: (v.kind === "report" ? (v.reportCategory || "-") : (v.violationType || "-")) + " — " + (VST[v.status] || v.status), at: v.createdAt }));
    flags.forEach(f => out.push({ id: "flag:" + f._id, kind: "flag", title: f.title || CY_RULE_TITLE[f.kind] || "عملية مشبوهة", details: f.details || "", at: f.lastAt || f.createdAt }));
    devs.forEach(c => out.push({ id: "case:" + c._id, kind: "case", title: "دخول جهاز على حساب عضو ثاني", details: "جهاز " + (c.targetName || "") + " دخل حساب " + (c.relatedName || ""), at: c.createdAt }));
    logs.forEach(l => out.push({ id: "log:" + l._id, kind: "log", title: l.action, details: l.details || "", at: l.createdAt }));
    sess.forEach(s => out.push({ id: "ses:" + s._id, kind: "ses", title: "تسجيل دخول للموقع", details: "IP: " + (s.ip || "-") + " — " + cyUaLabel(s.ua), at: s.loginAt }));
    out.sort((a, b) => new Date(b.at) - new Date(a.at));
    return out.slice(0, 150);
}
async function cyResolveOp(ref, targetUid) {
    const m = /^(log|ses|flag|case|vio):([a-f0-9]{24})$/.exec(String(ref || ""));
    if (!m) return null;
    if (m[1] === "vio") {
        const v = await Violation.findById(m[2], { photo: 0 }).lean();
        if (!v || v.reporterDiscord !== targetUid) return null;
        const lines = [(v.kind === "report" ? "تقرير مكافحة مخدرات: " + (v.reportCategory || "-") : "المخالفة: " + (v.violationType || "-")), "الحالة: " + ({ pending: "قيد المراجعة", approved: "مقبولة", rejected: "مرفوضة" }[v.status] || v.status)];
        if (v.rejectReason) lines.push("سبب الرفض: " + v.rejectReason);
        return { ref, title: v.kind === "report" ? "تسجيل تقرير" : "تسجيل مخالفة", lines, opAt: v.createdAt, hasPhoto: false };
    }
    if (m[1] === "flag") {
        const f = await CyberFlag.findById(m[2]).lean();
        if (!f || f.targetUid !== targetUid) return null;
        return { ref, title: f.title || CY_RULE_TITLE[f.kind] || "عملية مشبوهة", lines: [f.details || ""].filter(Boolean), opAt: f.lastAt || f.createdAt, hasPhoto: false };
    }
    if (m[1] === "case") {
        const c = await CyberCase.findById(m[2], { targetUid: 1, targetName: 1, relatedName: 1, createdAt: 1 }).lean();
        if (!c || c.targetUid !== targetUid) return null;
        return { ref, title: "دخول جهاز على حساب عضو ثاني", lines: ["جهاز " + (c.targetName || "") + " دخل حساب " + (c.relatedName || "")], opAt: c.createdAt, hasPhoto: false };
    }
    if (m[1] === "log") {
        const l = await Log.findById(m[2]).lean();
        if (!l || l.actorId !== targetUid) return null;
        const lines = [];
        if (l.details) lines.push(l.details);
        if (l.discordTag || l.discordId) lines.push("الشخص: " + (l.discordTag || l.discordId));
        return { ref, title: l.action, lines, opAt: l.createdAt, hasPhoto: false };
    }
    const s = await DeviceSession.findById(m[2]).lean();
    if (!s || s.uid !== targetUid) return null;
    const lines = ["عنوان الـ IP: " + (s.ip || "-"), "الجهاز: " + cyUaLabel(s.ua)];
    return { ref, title: "تسجيل دخول للموقع", lines, opAt: s.loginAt, hasPhoto: false };
}


// ================= قواعد العمليات المشبوهة (30 نوع) =================
// عدّل الأرقام من هنا إذا تبي الحساسية أقل أو أكثر
const CY_CFG = {
    ipN: 4, loginN: 6, sharedIpN: 4, ringN: 3, pileN: 3,
    devN: 3, hopIpN: 3, hopMs: 30 * 60000,
    perRuleCap: 15,
};
const CY_RULE_TITLE = {
    "multi-ip": "دخول من عدة عناوين IP",
    "login-burst": "تسجيل دخول متكرر بسرعة",
    "shared-ip": "عدة حسابات من نفس الشبكة",
    "device-ring": "جهاز واحد على 3 حسابات أو أكثر",
    "multi-device": "دخول من عدة أجهزة مختلفة",
    "ip-hop": "تغيير IP بسرعة غير طبيعية",
    "flag-pile": "تراكم عمليات مشبوهة على نفس الشخص",
};
const CY_FLAG_KINDS = ["multi-ip", "login-burst", "shared-ip", "device-ring", "multi-device", "ip-hop", "flag-pile"];
const cyH = s => crypto.createHash("sha1").update(String(s)).digest("hex").slice(0, 10);
function cySpan(ms) {
    if (ms < 60000) return "أقل من دقيقة";
    if (ms < 3600000) return Math.round(ms / 60000) + " دقيقة";
    return Math.round(ms / 3600000) + " ساعة";
}
function cyGroup(arr, fn) {
    const m = new Map();
    for (const x of arr) {
        const k = fn(x);
        if (k === null || k === undefined || k === "") continue;
        let a = m.get(k);
        if (!a) m.set(k, a = []);
        a.push(x);
    }
    return m;
}
// arr لازم تكون مرتبة تصاعدياً حسب get — ترجع أول نافذة فيها min عنصر أو أكثر
function cyHit(arr, win, min, get) {
    get = get || (x => x.t);
    let j = 0;
    for (let i = 0; i < arr.length; i++) {
        while (get(arr[i]) - get(arr[j]) > win) j++;
        if (i - j + 1 >= min) {
            let k = i;
            while (k + 1 < arr.length && get(arr[k + 1]) - get(arr[j]) <= win) k++;
            return arr.slice(j, k + 1);
        }
    }
    return null;
}
async function cyNamesMap(uids) {
    const m = new Map();
    uids = Array.from(new Set((uids || []).filter(Boolean)));
    if (!uids.length) return m;
    (await Personnel.find({ discord: { $in: uids } }, { discord: 1, registeredName: 1 }).lean()).forEach(p => { if (p.registeredName) m.set(p.discord, p.registeredName); });
    (await Account.find({ uid: { $in: uids } }, { uid: 1, fullName: 1, email: 1 }).lean()).forEach(a => { if (!m.has(a.uid)) m.set(a.uid, a.fullName || a.email); });
    return m;
}
async function cyEmitFlags(out) {
    if (!out.length) return 0;
    try {
        const per = new Map(), picked = [];
        out.sort((a, b) => (b.count || 0) - (a.count || 0));
        for (const o of out) {
            const n = per.get(o.rule) || 0;
            if (n >= CY_CFG.perRuleCap) continue;
            per.set(o.rule, n + 1);
            picked.push(o);
        }
        const nm = await cyNamesMap(picked.reduce((a, o) => a.concat([o.uid], o.uids || []), []));
        const byKey = new Map();
        for (const o of picked) {
            const key = ["r", o.rule, o.uid, Math.floor(o.anchor / CY_DAY), o.disc || ""].join(":");
            if (byKey.has(key)) continue;
            const details = typeof o.det === "function" ? o.det(nm) : o.det;
            byKey.set(key, { updateOne: {
                filter: { key },
                update: {
                    $setOnInsert: { key, kind: o.rule, status: "open", targetUid: o.uid, createdAt: new Date() },
                    $set: {
                        targetName: nm.get(o.uid) || o.name || o.uid, title: CY_RULE_TITLE[o.rule] || o.rule, details,
                        count: o.count || 1, violationIds: (o.vio || []).slice(0, 20), approvedBy: [],
                        firstAt: new Date(o.first || o.anchor), lastAt: new Date(o.last || o.anchor),
                    },
                },
                upsert: true,
            } });
        }
        const r = await CyberFlag.bulkWrite(Array.from(byKey.values()), { ordered: false });
        return r.upsertedCount || r.nUpserted || 0;
    } catch (e) { console.error("❌ cyEmitFlags:", e.message); return 0; }
}

let cyRulesAt = 0, cyRulesBusy = false;
async function cyScanRules() {
    if (cyRulesBusy || Date.now() - cyRulesAt < 120000) return;
    cyRulesBusy = true;
    try {
        const now = Date.now(), C = CY_CFG;
        const since7 = new Date(now - 7 * CY_DAY);
        const out = [];
        const skip = u => !u || u === "system" || isSeniorAdmin(u) || isOwnerUid(u);
        const add = (rule, uid, anchor, det, x) => { if (!skip(uid)) out.push(Object.assign({ rule, uid, anchor, det }, x || {})); };
        const run = async (rule, fn) => { try { await fn(); } catch (e) { console.error("❌ cyRule " + rule + ":", e.message); } };

        // ---------- تحميل بيانات الدخول ----------
        let S = [];
        await run("load-sess", async () => {
            const rows = await DeviceSession.find({ loginAt: { $gte: new Date(now - 2 * CY_DAY) } }, { uid: 1, ip: 1, ua: 1, loginAt: 1 }).limit(10000).maxTimeMS(10000).lean();
            S = rows.map(s => ({ uid: s.uid, ip: s.ip || "", ua: s.ua || "", t: +new Date(s.loginAt) })).sort((a, b) => a.t - b.t);
        });
        const weekAnchor = Math.floor(now / (7 * CY_DAY)) * 7 * CY_DAY;

        // ================= 26-29: الدخول والأجهزة =================
        const S24 = S.filter(s => s.t >= now - CY_DAY);
        await run("multi-ip", () => {
            for (const [u, arr] of cyGroup(S24, s => s.uid)) {
                const ips = Array.from(new Set(arr.map(s => s.ip).filter(Boolean)));
                if (ips.length >= C.ipN) add("multi-ip", u, arr[0].t, "دخل من " + ips.length + " عناوين IP مختلفة خلال 24 ساعة", { count: ips.length, first: arr[0].t, last: arr[arr.length - 1].t });
            }
        });
        await run("login-burst", () => {
            for (const [u, arr] of cyGroup(S, s => s.uid)) {
                const h = cyHit(arr, 3600000, C.loginN);
                if (h) add("login-burst", u, h[0].t, "سجّل دخول " + h.length + " مرات خلال " + cySpan(h[h.length - 1].t - h[0].t), { count: h.length, first: h[0].t, last: h[h.length - 1].t });
            }
        });
        await run("shared-ip", () => {
            for (const [ip, arr] of cyGroup(S24, s => s.ip)) {
                const us = Array.from(new Set(arr.map(s => s.uid)));
                if (us.length < C.sharedIpN) continue;
                const target = arr.slice().reverse().map(s => s.uid).find(u => !skip(u));
                if (!target) continue;
                add("shared-ip", target, arr[0].t, nm => us.length + " حسابات دخلت من نفس الشبكة خلال 24 ساعة: " + us.slice(0, 6).map(u => nm.get(u) || u).join("، "), { disc: cyH(ip), uids: us, count: us.length, first: arr[0].t, last: arr[arr.length - 1].t });
            }
        });
        await run("device-ring", async () => {
            const rings = await DeviceLink.find({ "accounts.2": { $exists: true } }, { accounts: 1 }).limit(200).maxTimeMS(8000).lean();
            for (const d of rings) {
                const accs = (d.accounts || []).slice().sort((a, b) => +new Date(b.firstSeen) - +new Date(a.firstSeen));
                if (accs.length < C.ringN) continue;
                const newest = accs[0], nt = +new Date(newest.firstSeen);
                if (!nt || nt < now - 7 * CY_DAY) continue;
                add("device-ring", newest.uid, nt, nm => "جهاز واحد دخلت منه " + accs.length + " حسابات: " + accs.slice(0, 6).map(a => nm.get(a.uid) || a.uid).join("، "), { disc: cyH(d._id), uids: accs.map(a => a.uid), count: accs.length, first: +new Date(accs[accs.length - 1].firstSeen), last: nt });
            }
        });

        await run("multi-device", () => {
            for (const [u, arr] of cyGroup(S24, s => s.uid)) {
                const devs = Array.from(new Set(arr.map(s => cyUaLabel(s.ua))));
                if (devs.length >= C.devN) add("multi-device", u, arr[0].t, "دخل من " + devs.length + " أجهزة مختلفة خلال 24 ساعة: " + devs.slice(0, 4).join("، "), { count: devs.length, first: arr[0].t, last: arr[arr.length - 1].t });
            }
        });
        await run("ip-hop", () => {
            for (const [u, arr] of cyGroup(S24, s => s.uid)) {
                const h = cyHit(arr, C.hopMs, C.hopIpN);
                if (!h) continue;
                const ips = Array.from(new Set(h.map(s => s.ip).filter(Boolean)));
                if (ips.length >= C.hopIpN) add("ip-hop", u, h[0].t, "غيّر الـ IP " + ips.length + " مرات خلال " + cySpan(h[h.length - 1].t - h[0].t), { count: ips.length, first: h[0].t, last: h[h.length - 1].t });
            }
        });

        const fresh = await cyEmitFlags(out);

        // ================= 30: تراكم العمليات المشبوهة على نفس الشخص =================
        const pile = [];
        await run("flag-pile", async () => {
            const rows = await CyberFlag.aggregate([
                { $match: { createdAt: { $gte: since7 }, status: { $in: ["open", "investigated"] }, kind: { $ne: "flag-pile" } } },
                { $group: { _id: "$targetUid", n: { $sum: 1 }, first: { $min: "$firstAt" }, last: { $max: "$lastAt" }, name: { $first: "$targetName" } } },
                { $match: { n: { $gte: C.pileN } } },
                { $limit: 50 },
            ]).option({ maxTimeMS: 8000 });
            for (const g of rows) if (!skip(g._id)) pile.push({ rule: "flag-pile", uid: g._id, anchor: weekAnchor, det: g.n + " عمليات مشبوهة مفتوحة على نفس الشخص خلال آخر 7 أيام", count: g.n, name: g.name, first: g.first ? +new Date(g.first) : weekAnchor, last: g.last ? +new Date(g.last) : weekAnchor });
        });
        const fresh2 = await cyEmitFlags(pile);
        if (fresh + fresh2 > 0) cyberPush(null);
    } catch (e) { console.error("❌ cyScanRules:", e.message); }
    finally { cyRulesAt = Date.now(); cyRulesBusy = false; }
}
setTimeout(() => { cyScanRules().catch(() => {}); }, 45000);
