app.post("/api/court/:id/mute", ensureAuth, async (req, res) => {
    const x = await courtAccess(req, res, false); if (!x) return;
    if (x.c.status !== "active") return res.status(400).json({ error: "المحكمة منتهية" });
    if (x.isT) return res.status(403).json({ error: "ليست لديك صلاحية" });
    const target = String((req.body || {}).uid || ""), on = !!(req.body || {}).on;
    if (!target || target === req.user.id) return res.status(400).json({ error: "حدد الشخص" });
    if (!x.r.leader && !courtIsTarget(x.c, target)) return res.status(403).json({ error: "تقدر تسكّت المتحقق معه فقط" });
    await CourtCase.updateOne({ _id: x.c._id }, on ? { $addToSet: { muted: target } } : { $pull: { muted: target } });
    const vm = x.c.voiceN ? offLive.get(x.c.voiceN) : null;
    if (vm && vm.has(target)) { vm.get(target).muted = on; offPushState(x.c.voiceN); }
    res.json({ ok: true });
});
app.post("/api/court/:id/kick", ensureAuth, async (req, res) => {
    const x = await courtAccess(req, res, true); if (!x) return;
    if (x.c.status !== "active") return res.status(400).json({ error: "المحكمة منتهية" });
    const target = String((req.body || {}).uid || "");
    if (!target || target === req.user.id) return res.status(400).json({ error: "حدد الشخص" });
    if (isOwnerUid(target) && !isOwnerUid(req.user.id)) return res.status(403).json({ error: "ما يمديك تطرد المالك" });
    if (isSeniorAdmin(target) && !isSeniorAdmin(req.user.id)) return res.status(403).json({ error: "ما يمديك تطرد أحد من الكبار" });
    if (!courtIsTarget(x.c, target)) await CourtCase.updateOne({ _id: x.c._id }, { $addToSet: { kicked: target } });
    if (x.c.voiceN) { offSendTo(target, { t: "kicked", n: x.c.voiceN }); offRemove(target, x.c.voiceN); }
    res.json({ ok: true });
});

// ---------- فك الطرد (المحكمة + التحقيق العسكري + التحقيق السيبراني) ----------
async function kickCtx(req, res) {
    const n = offParseN(req.params.n);
    const uid = req.user.id;
    if (n && offIsCourt(n)) {
        const c = await CourtCase.findOne({ voiceN: n, status: "active" });
        if (!c) { res.status(404).json({ error: "المحكمة غير موجودة أو انتهت" }); return null; }
        const r = await courtRole(uid);
        if (courtIsTarget(c, uid) || !(r.leader || c.startedBy === uid)) { res.status(403).json({ error: "فك الطرد لقيادة الشؤون العسكرية أو اللي فتح التحقيق أو الكبار" }); return null; }
        return { type: "court", c, n };
    }
    if (n && offIsCyber(n)) {
        const c = await CyberCase.findOne({ voiceN: n, status: "investigating" });
        if (!c) { res.status(404).json({ error: "التحقيق غير موجود أو منتهي" }); return null; }
        const rl = await cyberRoleOf(uid);
        if (c.targetUid === uid || !(rl.isLeader || isSeniorAdmin(uid))) { res.status(403).json({ error: "فك الطرد لقيادة الأمن السيبراني فقط" }); return null; }
        return { type: "cyber", c, n };
    }
    res.status(400).json({ error: "الطرد من هذا الروم مؤقت، تقدر ترجع تدخل على طول" });
    return null;
}
app.get("/api/officers/rooms/:n/kicked", ensureAuth, async (req, res) => {
    const x = await kickCtx(req, res); if (!x) return;
    const list = [];
    for (const u of (x.c.kicked || [])) list.push({ uid: u, name: await cyName(u) });
    res.json({ list });
});
app.post("/api/officers/rooms/:n/unkick", ensureAuth, async (req, res) => {
    const x = await kickCtx(req, res); if (!x) return;
    const target = String((req.body || {}).uid || "");
    if (!(x.c.kicked || []).includes(target)) return res.status(404).json({ error: "هذا الشخص مو مطرود" });
    const Model = x.type === "court" ? CourtCase : CyberCase;
    await Model.updateOne({ _id: x.c._id }, { $pull: { kicked: target } });
    const name = await cyName(req.user.id), tn = await cyName(target);
    if (x.type === "cyber") { await cySystemMsg(x.c._id, "🔓 " + name + " فك الطرد عن " + tn); cyberPush(x.c); }
    await logEvent({ action: "فك طرد من روم", discordId: target, actorId: req.user.id, actorTag: name, details: tn + " — روم " + x.n });
    pushUid(target, { title: CONFIG.SITE_NAME, body: "🔓 تم فك الطرد عنك، تقدر تدخل الروم", tag: "unkick", ttl: 3600 }).catch(() => {});
    res.json({ ok: true });
});
app.post("/api/cyber/cases/:id/unkick", ensureAuth, async (req, res) => {
    try {
        const x = await cyAccess(req, res, true); if (!x) return;
        const target = String((req.body && req.body.uid) || "");
        if (!(x.c.kicked || []).includes(target)) return res.status(404).json({ error: "هذا الشخص مو مطرود" });
        await CyberCase.updateOne({ _id: x.c._id }, { $pull: { kicked: target } });
        const name = await cyName(req.user.id), tn = await cyName(target);
        await cySystemMsg(x.c._id, "🔓 " + name + " فك الطرد عن " + tn);
        cyberPush(x.c);
        pushUid(target, { title: CONFIG.SITE_NAME, body: "🔓 تم فك الطرد عنك من التحقيق", tag: "unkick", ttl: 3600 }).catch(() => {});
        res.json({ ok: true });
    } catch (e) { res.status(500).json({ error: "تعذر فك الطرد" }); }
});

// لما يجي موعد المحكمة تنفتح تلقائياً: العضو ينقفل عليه وينفتح الروم الصوتي
async function courtActivate(c) {
    if (courtTargetUids(c).some(u => underCourt.has(u))) return;
    const used = new Set((await CourtCase.find({ status: "active", voiceN: { $ne: null } }, { voiceN: 1 }).lean()).map(z => z.voiceN));
    let n = 950; while (used.has(n) && n < 979) n++;
    if (used.has(n)) return; // المحكمة ممتلئة، يعيد المحاولة بالدورة الجاية
    const u = await CourtCase.findOneAndUpdate({ _id: c._id, status: "scheduled" }, { $set: { status: "active", voiceN: n, startedAt: new Date() } }, { new: true });
    if (!u) return;
    courtKindByN.set(n, u.kind === "inv" ? "inv" : "court");
    courtTargetUids(u).forEach(t => { soonCourt.delete(t); underCourt.set(t, courtLite(u)); });
    await logEvent({ action: u.kind === "inv" ? "بدء تحقيق عسكري" : "بدء محكمة عسكرية", discordId: u.targetUid, actorId: "system", actorTag: "النظام", details: courtTargetNames(u) + (u.reason ? " — " + u.reason : "") });
    courtPush(courtTargetUids(u));
    sseBroadcast("courtlock", { t: Date.now() }, cl => courtIsTarget(u, cl.uid));
    courtTargetUids(u).forEach(t => pushUid(t, { title: CONFIG.SITE_NAME, body: courtIcon(u) + " أنت مطلوب " + courtFor(u) + "، ادخل الموقع الحين", tag: "court", ttl: 1800 }).catch(() => {}));
}
let _courtTicking = false;
async function courtTick() {
    if (_courtTicking) return;
    _courtTicking = true;
    try {
        await loadCourt();   // مزامنة الذاكرة مع القاعدة (لو انحذفت محكمة يدوياً من القاعدة)
        const due = await CourtCase.find({ status: "scheduled", at: { $lte: new Date() } }).sort({ at: 1 }).limit(10);
        for (const c of due) await courtActivate(c);
    } catch (e) { console.error("❌ courtTick:", e.message); }
    _courtTicking = false;
}
setInterval(courtTick, 15000);

// الصفحة ثابتة (ما تتغير بين الطلبات) => نضغطها مرة وحدة ونرسلها gzip: ٦٢٠KB تصير ~١٣٠KB
let __flHtmlCache = null;
function flSendHtml(req, res, html) {
    try {
        if (!__flHtmlCache) {
            const raw = Buffer.from(html, "utf8");
            __flHtmlCache = { raw, gz: require("zlib").gzipSync(raw, { level: 9 }) };
        }
        res.set("Vary", "Accept-Encoding");
        res.type("html");
        if (/\bgzip\b/.test(String(req.headers["accept-encoding"] || ""))) {
            res.set("Content-Encoding", "gzip");
            return res.end(__flHtmlCache.gz);
        }
        return res.end(__flHtmlCache.raw);
    } catch (e) { return res.send(html); }
}
