    var tabs = senior ? [['waiting', '⏳ انتظار الإدارة'], ['active', '✅ قيد المتابعة'], ['ai', '🤖 عند المساعد'], ['closed', '🔒 مغلقة'], ['rates', '⭐ التقييمات'], ['bans', '🚫 المحظورين']] : [['waiting', '⏳ انتظار الإدارة']];
