            P.stream = new MediaStream([e.track]);
            offRecAddPeer(uid);
            P.audioEl.srcObject = P.stream;
            var pp = P.audioEl.play(); if (pp && pp.catch) pp.catch(function () {});
            offWatch(uid, P.stream, P);
