async function courtRecordsLoad() {
    var b = document.getElementById('ct-sub-body'); if (!b) return;
    b.innerHTML = '<div class="card">جارِ التحميل...</div>';
    try {
        var d = await api('/api/court/admin/records?kind=' + (COURT.akind || 'court'), { noLock: true });
        b = document.getElementById('ct-sub-body'); if (!b) return;
        b.innerHTML = d.list.length ? d.list.map(courtRecRow).join('') : '<div class="card" style="color:var(--muted);text-align:center;">ما فيه سجلات للحين</div>';
    } catch (e) { if (b) b.innerHTML = '<div class="card" style="color:#f87171;">' + spEsc(e.message) + '</div>'; }
}
function courtRecRow(c) {
    var lbl = c.status === 'active' ? 'جارية' : (c.status === 'ended' ? 'منتهية' : 'ملغية');
    var cls = c.status === 'ended' ? 'approved' : (c.status === 'active' ? 'pending' : 'rejected');
    var mins = Math.max(1, Math.round(((c.endedAt ? new Date(c.endedAt).getTime() : Date.now()) - new Date(c.startedAt).getTime()) / 60000));
    var meta = (c.reason ? 'السبب: ' + spEsc(c.reason) + ' • ' : '') + 'فتحه: ' + spEsc(c.byName || '-') + ' • ' + flTime(c.startedAt) + ' • المدة: ' + mins + ' د' + (c.endedByName ? ' • أنهاها: ' + spEsc(c.endedByName) : '');
    return '<div class="card"><div class="row"><div><b>' + spEsc(c.targetName || '') + '</b> <span class="badge ' + cls + '">' + lbl + '</span>' +
        '<div style="color:var(--muted);font-size:12px;margin-top:3px;">' + meta + '</div></div>' +
        '<button class="btn sm" data-id="' + c.id + '" onclick="courtReplay(this.dataset.id)">' + (c.recs ? '🎧 استماع للسجل' : '🎬 عرض السجل (بدون صوت)') + '</button></div></div>';
}
async function courtReplay(id) {
    try {
        var d = await api('/api/court/admin/' + id + '/session', { noLock: true });
        OFFA.data = { sessions: [d.session] };
        offaReplay(0);
    } catch (e) { toast(e.message); }
}
function courtAtText(at) {
    try { return new Date(at).toLocaleString('ar-SA', { timeZone: 'Asia/Riyadh', weekday: 'long', day: 'numeric', month: 'long', hour: 'numeric', minute: '2-digit' }); }
    catch (e) { return String(at || ''); }
}
function courtSoonHtml() {
    var m = ME && ME.courtSoon;
    if (!m) return '';
    var minv = m.kind === 'inv';
    return '<div class="card" style="border-color:rgba(234,179,8,.5);"><b>' + (minv ? '🔎 عليك موعد تحقيق عسكري' : '⚖️ عليك موعد محكمة عسكرية') + '</b><div style="color:var(--muted);font-size:13px;margin-top:4px;">الموعد: ' + spEsc(courtAtText(m.at)) + '<br>وقت الموعد ينقفل حسابك لين تدخل ' + (minv ? 'التحقيق' : 'المحكمة') + '، جهّز نفسك.</div></div>';
}
function courtSoonPaint() { var b = document.getElementById('court-soon'); if (b) b.innerHTML = courtSoonHtml(); }
function courtJoin(n) {
    flAskNotif();
    if (typeof VC !== 'undefined' && VC) { toast('أنت داخل روم حالياً'); return; }
    offJoinVoice(n);
}
function courtKindOfId(id) {
    var st = COURT.st, k = COURT.kind === 'inv' ? 'inv' : 'court';
    if (st) ['pending', 'scheduled', 'active'].forEach(function (g) { (st[g] || []).forEach(function (x) { if (x.id === id) k = x.kind === 'inv' ? 'inv' : 'court'; }); });
    return k;
}
async function courtEnd(id) {
    var inv = courtKindOfId(id) === 'inv';
    if (!(await confirmModal(inv ? 'تنهي هذا التحقيق وتفك التقييد عن العضو؟' : 'تنهي هذي المحكمة وتفك التقييد عن العضو؟'))) return;
    try { await api('/api/court/' + id + '/end', { method: 'POST', body: '{}' }); toast(inv ? 'تم إنهاء التحقيق' : 'تم إنهاء المحكمة'); courtPanelLoad(true); }
    catch (e) { toast(e.message); }
}
function courtEndFromRoom() {
    if (!VC || !VC.caseId) return;
    var id = VC.caseId;
    confirmModal((VC.state && VC.state.inv) ? 'تنهي التحقيق وتفك التقييد عن العضو؟' : 'تنهي المحكمة وتفك التقييد عن العضو؟').then(function (ok) {
        if (!ok) return;
        api('/api/court/' + id + '/end', { method: 'POST', body: '{}' }).catch(function (e) { toast(e.message); });
    });
}
function courtKick(uid) {
    if (!VC || !VC.caseId) return;
    var id = VC.caseId;
    confirmModal((VC.state && VC.state.inv) ? 'تطرده من التحقيق؟' : 'تطرده من المحكمة؟').then(function (ok) {
        if (!ok) return;
        api('/api/court/' + id + '/kick', { method: 'POST', body: JSON.stringify({ uid: uid }) }).catch(function (e) { toast(e.message); });
    });
}
function courtMute(uid, m) {
    if (!VC || !VC.caseId) return;
    api('/api/court/' + VC.caseId + '/mute', { method: 'POST', body: JSON.stringify({ uid: uid, on: String(m) === '1' }) }).catch(function (e) { toast(e.message); });
}
function courtPanelClose() {
    if (COURT.panelTimer) { clearInterval(COURT.panelTimer); COURT.panelTimer = null; }
    renderDashboard();
}
function courtMount(hostId, kind) {
    var host = document.getElementById(hostId);
    if (!host) return;
    COURT.kind = kind === 'inv' ? 'inv' : 'court';
    host.innerHTML = '<div id="court-body"><div class="card">جارِ التحميل...</div></div>';
    courtPanelLoad(false);
    if (COURT.panelTimer) clearInterval(COURT.panelTimer);
    COURT.panelTimer = setInterval(function () {
        if (document.getElementById('court-body')) courtPanelLoad(true);
        else { clearInterval(COURT.panelTimer); COURT.panelTimer = null; }
    }, 8000);
}
function renderInvPanel() { renderCourtPanel('inv'); }
function renderCourtPanel(kind) {
    if (!ME || !ME.courtStaff) return renderDashboard();
    document.getElementById('app').innerHTML =
        '<div class="card row"><h2>' + (kind === 'inv' ? '🔎 التحقيق العسكري' : '⚖️ المحكمة العسكرية') + '</h2><button class="btn gray sm" onclick="courtPanelClose()">رجوع للوحتي</button></div>' +
        '<div id="court-host"></div>';
    courtMount('court-host', kind);
}
function mpMemberTab(name, el) {
    document.querySelectorAll('.tab').forEach(function (t) { t.classList.remove('active'); });
    if (el) el.classList.add('active');
    var main = document.getElementById('mp-member-main'), ct = document.getElementById('mp-member-court');
    if (!main || !ct) return;
    if (name === 'court' || name === 'inv') { main.style.display = 'none'; ct.style.display = 'block'; courtMount('mp-member-court', name); }
    else { ct.style.display = 'none'; ct.innerHTML = ''; main.style.display = 'block'; }
}
function courtBtn(label, cls, a, id) {
    return '<button class="btn sm ' + cls + '" data-a="' + a + '" data-id="' + id + '" onclick="courtAct(this.dataset.a, this.dataset.id)">' + label + '</button>';
}
function courtMembersHtml(c) {
    if (!c.members || !c.members.length) return '';
    var roles = { target: '⚖️ المتحقق معه', starter: '🧾 فاتح التحقيق', member: '👮 مشارك' };
    var act = c.status === 'active';
    return '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px;">' + c.members.map(function (m) {
        return '<span class="pt-chip ' + (act ? (m.inRoom ? 'on' : 'off') : '') + '">' + (roles[m.role] || '') + ': ' + spEsc(m.name || '-') + (act ? (m.inRoom ? ' • داخل الروم' : ' • خارج الروم') : '') + '</span>';
    }).join('') + '</div>';
}
function courtCaseHtml(c, st) {
    var s = c.status;
    var canCancel = st.leader || c.by === ME.discordId;
    var meta = (c.reason ? 'السبب: ' + spEsc(c.reason) + ' • ' : '') + 'فتحه: ' + spEsc(c.byName || '-');
    if (s === 'pending' && c.joinTo) meta += ' • 📌 طلب ضم لـ' + (c.kind === 'inv' ? 'تحقيق' : 'محكمة') + ' قائم';
    if (s === 'pending' || s === 'scheduled') meta += ' • 🕒 الموعد: ' + spEsc(courtAtText(c.at));
    if (s === 'scheduled' && c.approvedByName) meta += ' • وافق: ' + spEsc(c.approvedByName);
    if (s === 'active') meta += ' • بدأت: ' + flTime(c.startedAt);
    if (c.endedByName && (s === 'ended' || s === 'cancelled' || s === 'rejected')) meta += ' • ' + (s === 'ended' ? 'أنهاها' : s === 'cancelled' ? 'ألغاها' : 'رفضها') + ': ' + spEsc(c.endedByName);
    var btns = '';
    if (s === 'pending') {
        if (st.leader) btns = courtBtn('✅ قبول', '', 'approve', c.id) + courtBtn('❌ رفض', 'danger', 'reject', c.id);
        else if (canCancel) btns = courtBtn('❌ إلغاء الطلب', 'danger', 'cancel', c.id);
    } else if (s === 'scheduled') {
        if (canCancel) btns = courtBtn(c.kind === 'inv' ? '❌ إلغاء التحقيق' : '❌ إلغاء المحكمة', 'danger', 'cancel', c.id);
    } else if (s === 'active') {
        btns = '<button class="btn sm" onclick="courtJoin(' + c.n + ')">🎙️ دخول ' + (c.kind === 'inv' ? 'التحقيق' : 'المحكمة') + '</button>' + (canCancel ? '<button class="btn sm gray" onclick="courtKickedPanel(' + c.n + ')">🔓 المطرودين</button>' + courtBtn(c.kind === 'inv' ? '❌ إلغاء التحقيق' : '❌ إلغاء المحكمة', 'danger', 'cancel', c.id) : '');
    } else {
        btns = '<span class="badge ' + (s === 'ended' ? 'approved' : 'rejected') + '">' + (s === 'ended' ? 'منتهية' : s === 'cancelled' ? 'ملغية' : 'مرفوضة') + '</span>';
    }
    return '<div class="card"><div class="row"><div><b>' + (c.kind === 'inv' ? '🔎 ' : '⚖️ ') + spEsc(c.targetName || '') + '</b>' +
        '<div style="color:var(--muted);font-size:12px;margin-top:3px;">' + meta + '</div></div>' +
        '<div class="row" style="gap:6px;">' + btns + '</div></div>' + courtMembersHtml(c) + '</div>';
}
function courtHoursOpts(hh) {
    var hours = '';
    for (var i = 0; i < 24; i++) hours += '<option value="' + i + '"' + (i === hh ? ' selected' : '') + '>' + (i % 12 === 0 ? 12 : i % 12) + ' ' + (i < 12 ? 'صباحاً' : 'مساءً') + '</option>';
    return hours;
}
async function courtKickedPanel(n) {
    var box = document.getElementById('wf-box'); if (!box) return;
    box.innerHTML = '<h3>🔓 المطرودين</h3><div style="color:var(--muted);">جارِ التحميل...</div>';
    document.getElementById('wf-overlay').classList.add('open');
    try {
        var d = await api('/api/officers/rooms/' + n + '/kicked', { noLock: true });
        var h = '<h3>🔓 المطرودين</h3>';
        if (!(d.list || []).length) h += '<div style="color:var(--muted);margin:8px 0;">ما فيه أحد مطرود.</div>';
        (d.list || []).forEach(function (x) {
            h += '<div class="card row" style="padding:8px 12px;margin-top:6px;"><span>🚫 ' + spEsc(x.name) + '</span><button class="btn sm" data-n="' + n + '" data-u="' + x.uid + '" onclick="courtUnkickPanel(this.dataset.n, this.dataset.u)">🔓 فك الطرد</button></div>';
        });
        box.innerHTML = h + '<div class="wf-actions"><button class="btn gray sm" onclick="closeWarnForm()">إغلاق</button></div>';
    } catch (e) { box.innerHTML = '<h3>🔓 المطرودين</h3><div style="color:#f87171;">' + spEsc(e.message) + '</div><div class="wf-actions"><button class="btn gray sm" onclick="closeWarnForm()">إغلاق</button></div>'; }
}
async function courtUnkickPanel(n, uid) {
    try { await api('/api/officers/rooms/' + n + '/unkick', { method: 'POST', body: JSON.stringify({ uid: uid }) }); toast('🔓 تم فك الطرد'); courtKickedPanel(n); }
    catch (e) { toast(e.message); }
}
function courtApproveOpen(id) {
    var c = null, st = COURT.st;
    if (st) (st.pending || []).forEach(function (x) { if (x.id === id) c = x; });
    if (!c) { toast('الطلب مو موجود، حدّث الصفحة'); return; }
    var inv = c.kind === 'inv';
    var d = new Date(Math.max(new Date(c.at || Date.now()).getTime(), Date.now()));
    var today = '', hh = 12, mm = 0;
    try { today = d.toLocaleDateString('en-CA', { timeZone: 'Asia/Riyadh' }); } catch (e) {}
    try {
        var tt = d.toLocaleTimeString('en-GB', { timeZone: 'Asia/Riyadh', hour12: false, hour: '2-digit', minute: '2-digit' }).split(':');
        hh = parseInt(tt[0], 10) % 24; mm = parseInt(tt[1], 10) || 0;
    } catch (e) {}
    COURT.ap = { id: id, name: c.targetName, kind: c.kind, body: null };
    var box = document.getElementById('wf-box');
    box.innerHTML = '<h3>✅ قبول ' + (inv ? 'طلب التحقيق' : 'طلب المحكمة') + ' مع ' + spEsc(c.targetName || '') + '</h3>' +
        '<div style="color:var(--muted);font-size:12px;margin-bottom:6px;">حدد الموعد (الموعد المطلوب مكتوب، تقدر تغيّره).</div>' +
        (inv ? '<label style="display:flex;gap:8px;align-items:center;margin-top:8px;"><input type="checkbox" id="ap-now" onchange="courtApNow()" style="width:auto;"> فتح التحقيق الحين (على طول)</label>' : '') +
        '<div id="ap-when"><label>اليوم</label><input type="date" id="ap-date" value="' + today + '">' +
        '<label>الساعة</label><select id="ap-hour">' + courtHoursOpts(hh) + '</select>' +
        '<label>الدقيقة</label><input type="number" id="ap-min" min="0" max="59" value="' + mm + '"></div>' +
        '<div class="wf-actions"><button class="btn gray sm" onclick="closeWarnForm()">إلغاء</button>' +
        '<button class="btn sm" id="ap-go" onclick="courtApproveSubmit()">✅ قبول وتحديد الموعد</button></div>';
    document.getElementById('wf-overlay').classList.add('open');
}
function courtApNow() { var c = document.getElementById('ap-now'), w = document.getElementById('ap-when'); if (c && w) w.style.display = c.checked ? 'none' : 'block'; }
async function courtApproveSubmit(mode, joinId) {
    var ap = COURT.ap; if (!ap) return;
    if (!ap.body) {
        var nowEl = document.getElementById('ap-now');
        ap.body = { date: document.getElementById('ap-date').value, hour: document.getElementById('ap-hour').value, minute: document.getElementById('ap-min').value, now: !!(nowEl && nowEl.checked) };
        if (!ap.body.now && !ap.body.date) { ap.body = null; return toast('حدد اليوم'); }
        if (!ap.body.now && ap.body.minute === '') { ap.body = null; return toast('اكتب الدقيقة'); }
    }
    var body = Object.assign({}, ap.body, { mode: mode || '', joinId: joinId || null });
    var btn = document.getElementById('ap-go'); if (btn) btn.disabled = true;
    try {
        var r = await api('/api/court/' + ap.id + '/approve', { method: 'POST', body: JSON.stringify(body) });
        closeWarnForm(); COURT.ap = null;
        toast(r.joined ? '👥 تم القبول وضمه للقائم' : '✅ تم القبول وتحدد الموعد');
        courtPanelLoad(true);
    } catch (e) {
        if (e && e.data && e.data.choose) { courtApproveChoose(e.data.cases || []); return; }
        ap.body = null; toast(e.message); if (btn) btn.disabled = false;
    }
}
function courtApproveChoose(cases) {
    var ap = COURT.ap || {};
    var inv = ap.kind === 'inv';
    var box = document.getElementById('wf-box'); if (!box) return;
    box.innerHTML = '<h3>' + (inv ? '🔎 فيه تحقيق قائم' : '⚖️ فيه محكمة قائمة') + '</h3>' +
        '<div style="color:var(--muted);font-size:13px;line-height:1.9;margin-bottom:6px;">تبي تضم <b>' + spEsc(ap.name || 'العضو') + '</b> ' + (inv ? 'لتحقيق' : 'لمحكمة') + ' قائم، أو يكون ' + (inv ? 'تحقيق منفصل' : 'محكمة منفصلة') + '؟</div>' +
        cases.map(function (c) {
            var when = c.status === 'active' ? '🔴 جاري الحين' : '🕒 الموعد: ' + courtAtText(c.at);
            return '<div class="card" style="padding:10px;margin-top:8px;"><b>' + (c.kind === 'inv' ? '🔎 ' : '⚖️ ') + spEsc(c.targetName) + '</b><div style="color:var(--muted);font-size:12px;margin:4px 0 8px;">' + when + '</div>' +
                '<button class="btn sm" data-m="join" data-id="' + c.id + '" onclick="courtApproveSubmit(this.dataset.m, this.dataset.id)">👥 ضمه لهذا</button></div>';
        }).join('') +
        '<div class="wf-actions" style="margin-top:12px;"><button class="btn gray sm" onclick="closeWarnForm()">إلغاء</button>' +
        '<button class="btn sm" data-m="separate" onclick="courtApproveSubmit(this.dataset.m)">➕ ' + (inv ? 'تحقيق منفصل' : 'محكمة منفصلة') + '</button></div>';
}
async function courtAct(a, id) {
    if (a === 'approve') return courtApproveOpen(id);
    var inv = courtKindOfId(id) === 'inv';
    var q = { approve: null, reject: inv ? 'ترفض طلب التحقيق؟' : 'ترفض طلب المحكمة؟', cancel: inv ? 'تلغي هذا التحقيق؟ (لو كان جاري يتفك التقييد عن العضو)' : 'تلغي هذي المحكمة؟ (لو كانت جارية يتفك التقييد عن العضو)' }[a];
    if (q && !(await confirmModal(q))) return;
    try {
        await api('/api/court/' + id + (a === 'cancel' ? '/end' : '/' + a), { method: 'POST', body: '{}' });
        toast(a === 'approve' ? (inv ? '✅ تم القبول وتحدد موعد التحقيق' : '✅ تم القبول وتحدد موعد المحكمة') : a === 'reject' ? 'تم رفض الطلب' : (inv ? 'تم إلغاء التحقيق' : 'تم إلغاء المحكمة'));
        courtPanelLoad(true);
    } catch (e) { toast(e.message); }
}
async function courtPanelLoad(silent) {
    var box = document.getElementById('court-body');
    if (!box) return;
    var st;
    try { st = await api('/api/court/state?kind=' + (COURT.kind || 'court'), { noLock: true }); }
    catch (e) { if (!silent) box.innerHTML = '<div class="card" style="color:#f87171;">تعذر التحميل. (' + e.message + ')</div>'; return; }
    if (!document.getElementById('court-body')) return;
    COURT.st = st;
    var cinv = COURT.kind === 'inv';
    var typing = document.activeElement && document.activeElement.id === 'court-q';
    var h = '';
    if (ME.isSeniorAdmin) {
        h += '<div class="card"><h3>➕ ' + (cinv ? 'فتح تحقيق مع عضو' : 'إدخال عضو للمحكمة') + '</h3><div style="color:var(--muted);font-size:12px;margin-bottom:8px;">كبار المسؤولين يدخلون أي عضو للمحكمة حتى لو ما عليه تحقيق، ويحددون الموعد.</div>' +
            '<input id="court-q" placeholder="🔍 ابحث عن اسم العضو..." oninput="courtSearch(this.value)"><div id="court-cand"></div></div>';
    } else {
        h += '<div class="card" style="color:var(--muted);font-size:13px;">لفتح محكمة أو تحقيق مع عضو: روح لتاب الأعضاء واضغط زر «⚖️ محكمة» أو «🔎 تحقيق» جنبه. ' + (st.leader ? 'تحقيقاتك ينحدد موعدها على طول.' : 'الطلب يروح لقيادة الشؤون العسكرية وإذا وافقوا ينحدد الموعد.') + '</div>';
    }
    if (st.pending.length) h += '<h3 style="margin:14px 0 8px;">📥 طلبات التحقيق (' + st.pending.length + ')</h3>' + st.pending.map(function (c) { return courtCaseHtml(c, st); }).join('');
    h += '<h3 style="margin:14px 0 8px;">🕒 ' + (cinv ? 'تحقيقات مجدولة' : 'محاكم مجدولة') + ' (' + st.scheduled.length + ')</h3>' +
        (st.scheduled.length ? st.scheduled.map(function (c) { return courtCaseHtml(c, st); }).join('') : '<div class="card" style="color:var(--muted);">' + (cinv ? 'لا يوجد تحقيقات مجدولة' : 'لا يوجد محاكم مجدولة') + '</div>');
    h += '<h3 style="margin:14px 0 8px;">🔴 ' + (cinv ? 'التحقيقات الجارية' : 'المحاكمات الجارية') + ' (' + st.active.length + ')</h3>' +
        (st.active.length ? st.active.map(function (c) { return courtCaseHtml(c, st); }).join('') : '<div class="card" style="color:var(--muted);">' + (cinv ? 'لا يوجد تحقيقات جارية' : 'لا يوجد محاكمات جارية') + '</div>');
    if (st.recent.length) h += '<h3 style="margin:14px 0 8px;">📜 ' + (cinv ? 'سجل التحقيقات' : 'آخر المنتهية') + '</h3>' + st.recent.map(function (c) { return courtCaseHtml(c, st); }).join('');
    if (typing) {
        var keep = document.getElementById('court-q').value;
        box.innerHTML = h;
        var qi = document.getElementById('court-q'); if (qi) { qi.value = keep; qi.focus(); }
    } else box.innerHTML = h;
}
var courtSearchTimer = null;
function courtCandBtns(p) {
    var n = spEsc(p.registeredName);
    if (COURT.kind === 'inv') return '<button class="btn sm" style="background:#0f766e;" data-u="' + p.discord + '" data-n="' + n + '" onclick="invStart(this.dataset.u, this.dataset.n)">🔎 تحقيق</button>';
    return '<button class="btn sm" data-u="' + p.discord + '" data-n="' + n + '" onclick="courtStart(this.dataset.u, this.dataset.n)">⚖️ محكمة</button>';
}
function courtSearch(q) {
    clearTimeout(courtSearchTimer);
    courtSearchTimer = setTimeout(async function () {
        var box = document.getElementById('court-cand'); if (!box) return;
        if (!q || !q.trim()) { box.innerHTML = ''; return; }
        box.innerHTML = 'جارِ البحث...';
        try {
            var r = await api('/api/senior/personnel?q=' + encodeURIComponent(q), { noLock: true });
            var list = (r.list || []).filter(function (p) { return p.registeredName; });
            if (!list.length) { box.innerHTML = '<p style="color:var(--muted);font-size:13px;">لا نتائج</p>'; return; }
            box.innerHTML = list.slice(0, 15).map(function (p) {
                return '<div class="card" style="padding:8px 12px;margin-top:6px;"><div class="row"><span>' + spEsc(p.registeredName) + ' <span style="color:var(--muted);font-size:12px;">(' + spEsc(p.unit || '-') + ' • ' + spEsc(p.rank || '') + ')</span></span>' +
                    courtCandBtns(p) + '</div></div>';
            }).join('');
        } catch (e) { box.innerHTML = '<p style="color:#f87171;font-size:13px;">' + e.message + '</p>'; }
    }, 350);
}

/* ---------------- تاب الترددات (كبار المسؤولين) ---------------- */
async function flFreqAdmin() {
    var box = document.getElementById('admin-content');
    if (!box) return;
    box.innerHTML = '<div class="card">جارِ التحميل...</div>';
    var d;
    try { d = await api('/api/freq/list'); }
    catch (e) { if (currentAdminTab !== 'freq') return; box.innerHTML = '<div class="card" style="color:#f87171;">تعذر التحميل. (' + e.message + ')</div>'; return; }
    if (currentAdminTab !== 'freq') return;
    var extra = d.list.filter(function (f) { return !f.main; });
    box.innerHTML = '<div class="card"><h3>📻 الترددات</h3>' +
        '<div style="color:var(--muted);font-size:12px;margin-bottom:8px;">تردد القطاعات المشتركة موجود للجميع، وتقدر تسوي ' + d.max + ' ترددات إضافية.</div>' +
        d.list.map(function (f) {
            return '<div class="card" style="padding:8px 12px;margin-top:6px;"><div class="row"><span>' + (f.main ? '⭐ ' : '') + spEsc(f.name) + ' <span style="color:var(--muted);font-size:12px;">(' + f.count + ' متصل)</span></span>' +
                (f.main ? '<span style="color:var(--muted);font-size:12px;">الأساسي</span>' : '<button class="btn danger sm" onclick="flFreqDel(' + f.n + ')">حذف</button>') + '</div></div>';
        }).join('') +
        '<div style="margin-top:12px;"><input id="freq-name" maxlength="40" placeholder="اسم التردد الجديد (اختياري)">' +
        '<button class="btn" ' + (extra.length >= d.max ? 'disabled' : '') + ' onclick="flFreqAdd()">➕ إضافة تردد (' + extra.length + '/' + d.max + ')</button></div></div>';
}
async function flFreqAdd() {
    var i = document.getElementById('freq-name');
    try { await api('/api/senior/freq', { method: 'POST', body: JSON.stringify({ name: i ? i.value : '' }) }); toast('تمت الإضافة'); flFreqAdmin(); }
    catch (e) { toast(e.message); }
}
async function flFreqDel(n) {
    if (!(await confirmModal('تحذف هذا التردد؟ بيطلع منه كل اللي فيه.'))) return;
    try { await api('/api/senior/freq/' + n, { method: 'DELETE' }); toast('تم الحذف'); flFreqAdmin(); }
    catch (e) { toast(e.message); }
}


/* ---------------- 🪖 المخالفات العسكرية ---------------- */
var MV = { people: [], sel: null };
async function renderMilViolation() {
    if (!attOk()) return;
    var app = document.getElementById('app');
    app.innerHTML = "<div class='card'>جارِ التحميل...</div>";
    try {
        var r = await api('/api/milviol/people');
        MV.people = r.list || []; MV.sel = null;
    } catch (e) { toast(e.message); return renderDashboard(); }
    app.innerHTML =
        "<div class='card'><div class='row'><h2>📝 تسجيل مخالفة</h2><button class='btn gray sm' onclick='renderDashboard()'>رجوع</button></div>" +
        "<label>العسكري المخالف (من فريق أول إلى جندي)</label>" +
        "<input id='mv-search' placeholder='🔍 ابحث بالاسم أو الرتبة أو رقم البطاقة...' oninput='mvFilter(this.value)'>" +
        "<div id='mv-sel' style='margin:8px 0;color:var(--muted);font-size:13px;'>لم تختر أحد بعد</div>" +
        "<div id='mv-list' style='max-height:260px;overflow:auto;'></div>" +
        "<label style='margin-top:10px;'>المخالفة اللي سواها (اكتبها كتابة)</label>" +
        "<textarea id='mv-text' rows='5' maxlength='1000' placeholder='اكتب وش المخالفة اللي سواها...'></textarea>" +
        "<button class='btn' id='mv-btn' style='margin-top:10px;' onclick='mvSubmit()'>إرسال للمراجعة</button></div>" +
        "<div class='card'><h3>مخالفاتي العسكرية المسجلة</h3><div id='mv-mine'>جارِ التحميل...</div></div>";
    mvFilter('');
    mvLoadMine();
}
var mvTimer = null;
function mvFilter(q) {
    var box = document.getElementById('mv-list');
    if (!box) return;
    q = String(q || '').trim();
    clearTimeout(mvTimer);
    if (!q) { mvRender(MV.people.slice(0, 80)); return; }
    mvTimer = setTimeout(async function () {
        try {
            var r = await api('/api/milviol/people?q=' + encodeURIComponent(q), { noLock: true });
            var b2 = document.getElementById('mv-list'); if (!b2) return;
            var seen = {}; (r.list || []).forEach(function (x) { seen[x.discord] = 1; MV.people.push(x); });
            mvRender(r.list || []);
        } catch (e) { var b3 = document.getElementById('mv-list'); if (b3) b3.innerHTML = "<p style='color:#f87171;font-size:13px;'>" + cyEsc(e.message) + "</p>"; }
    }, 300);
}
function mvRender(list) {
    var box = document.getElementById('mv-list');
    if (!box) return;
    box.innerHTML = list.length ? list.map(function (x) {
        return "<div class='card' style='padding:8px 12px;margin-top:6px;cursor:pointer;' data-id='" + cyEsc(x.discord) + "' onclick='mvPick(this.dataset.id)'>" +
            cyEsc(x.name) + " <span style='color:var(--muted);font-size:12px;'>(" + cyEsc(x.rank || '-') + (x.unit ? ' • ' + cyEsc(x.unit) : '') + ")</span></div>";
    }).join('') : "<p style='color:var(--muted);font-size:13px;'>ما فيه نتائج</p>";
}
function mvPick(id) {
    var x = MV.people.filter(function (p) { return p.discord === id; })[0];
    if (!x) return;
    MV.sel = x;
    var el = document.getElementById('mv-sel');
    if (el) el.innerHTML = "✅ المخالف: <b style='color:#4ade80;'>" + cyEsc(x.name) + "</b> (" + cyEsc(x.rank || '-') + ")";
}
async function mvSubmit() {
    if (!MV.sel) return toast('اختر العسكري المخالف أول');
    var t = (document.getElementById('mv-text').value || '').trim();
    if (!t) return toast('اكتب المخالفة');
    var btn = document.getElementById('mv-btn');
    if (btn) { btn.disabled = true; btn.textContent = 'جارِ الإرسال...'; }
    try {
        await api('/api/milviol/submit', { method: 'POST', body: JSON.stringify({ targetDiscord: MV.sel.discord, text: t }) });
        toast('✅ انرسلت المخالفة للمراجعة');
        renderMilViolation();
    } catch (e) {
        toast(e.message);
        if (btn) { btn.disabled = false; btn.textContent = 'إرسال للمراجعة'; }
    }
}
function mvStatusBadge(s) {
    return "<span class='badge " + s + "'>" + (s === 'pending' ? 'قيد المراجعة' : s === 'approved' ? 'مقبولة' : 'مرفوضة') + "</span>";
}
async function mvLoadMine() {
    var box = document.getElementById('mv-mine');
    if (!box) return;
    try {
        var r = await api('/api/milviol/mine');
        box.innerHTML = r.list.length ? r.list.map(function (v) {
            return "<div class='card' style='padding:10px;margin-top:6px;'><div class='row'><b>" + cyEsc(v.targetName) + " <span style='color:var(--muted);font-size:12px;'>(" + cyEsc(v.targetRank || '-') + ")</span></b>" + mvStatusBadge(v.status) + "</div>" +
                "<div style='font-size:13px;margin-top:4px;'>" + cyEsc(v.text) + "</div>" +
                (v.status === 'rejected' && v.rejectReason ? "<div style='font-size:12px;color:var(--muted);margin-top:4px;'>سبب الرفض: " + cyEsc(v.rejectReason) + "</div>" : '') + "</div>";
        }).join('') : "<p style='color:var(--muted);'>ما سجلت مخالفات عسكرية بعد</p>";
    } catch (e) { box.innerHTML = "<p style='color:#f87171;'>" + cyEsc(e.message) + "</p>"; }
}
function renderMilViolPanel() {
    document.getElementById('app').innerHTML =
        "<div class='card row'><h2>⚖️ مراجعة المخالفات العسكرية</h2><button class='btn gray sm' onclick='renderDashboard()'>رجوع للوحتي</button></div>" +
        "<div id='mvp-box'>جارِ التحميل...</div>";
    mvpLoad();
}
function mvpCard(v, actions) {
    return "<div class='card' style='padding:12px;margin-top:8px;'><div class='row'><b>" + cyEsc(v.targetName) + " <span style='color:var(--muted);font-size:12px;'>(" + cyEsc(v.targetRank || '-') + ")</span></b>" + mvStatusBadge(v.status) + "</div>" +
        "<div style='font-size:12px;color:var(--muted);margin-top:3px;'>سجّلها: " + cyEsc(v.reporterName) + " (" + cyEsc(v.reporterRank || '-') + ")</div>" +
        "<div style='font-size:14px;margin-top:6px;'>" + cyEsc(v.text) + "</div>" +
        (v.status === 'rejected' && v.rejectReason ? "<div style='font-size:12px;color:var(--muted);margin-top:4px;'>سبب الرفض: " + cyEsc(v.rejectReason) + "</div>" : '') +
        (v.reviewedByName ? "<div style='font-size:12px;color:var(--muted);margin-top:4px;'>راجعها: " + cyEsc(v.reviewedByName) + "</div>" : '') +
        (actions ? "<div class='row' style='gap:8px;margin-top:8px;justify-content:flex-start;'><button class='btn sm' data-id='" + v._id + "' onclick='mvDecide(this.dataset.id, true)'>✅ قبول</button><button class='btn danger sm' data-id='" + v._id + "' onclick='mvDecide(this.dataset.id, false)'>❌ رفض</button></div>" : '') + "</div>";
}
function mvpHtml(r) {
    return "<div class='card'><h3>بانتظار المراجعة (" + r.pending.length + ")</h3>" +
        (r.pending.length ? r.pending.map(function (v) { return mvpCard(v, true); }).join('') : "<p style='color:var(--muted);'>ما فيه مخالفات معلّقة 👌</p>") + "</div>" +
        "<div class='card'><h3>آخر القرارات</h3>" +
        (r.recent.length ? r.recent.map(function (v) { return mvpCard(v, false); }).join('') : "<p style='color:var(--muted);'>لا يوجد</p>") + "</div>";
}
async function mvpLoad() {
    var box = document.getElementById('mvp-box');
    if (!box) return;
    try {
        box.innerHTML = mvpHtml(await api('/api/milviol/review-list'));
    } catch (e) { box.innerHTML = "<div class='card' style='color:#f87171;'>" + cyEsc(e.message) + "</div>"; }
}
async function mvDecide(id, ok) {
    var body = {};
    if (ok) {
        if (!(await confirmModal('تقبل هذي المخالفة وتتسجل في ملف العسكري؟'))) return;
    } else {
        var reason = await promptModal('اكتب سبب الرفض');
        if (!reason || !String(reason).trim()) return;
        body.reason = String(reason).trim();
    }
    try {
        await api('/api/milviol/' + id + (ok ? '/approve' : '/reject'), { method: 'POST', body: JSON.stringify(body) });
        toast(ok ? '✅ انقبلت وانسجلت في ملفه' : '❌ انرفضت');
        if (document.getElementById('mvp-box')) mvpLoad(); else loadPending();
    } catch (e) { toast(e.message); }
}

/* ---------------- جهاز واحد بالحساب (آخر جهاز يفوز) ---------------- */
function flSessionKicked() {
    FLX.kicked = true;
    try { if (SP.es) { SP.es.close(); SP.es = null; } } catch (e) {}
    try { if (typeof pollTimer !== 'undefined' && pollTimer) clearInterval(pollTimer); } catch (e) {}
    document.body.classList.add('pwa-frozen');
    document.documentElement.classList.add('pwa-lock');
    var g = document.getElementById('sess-gate');
    if (!g) { g = document.createElement('div'); g.id = 'sess-gate'; g.className = 'pwa-overlay'; document.body.appendChild(g); }
    g.innerHTML = '<div class="pwa-box"><div style="font-size:54px">📵</div><h2>تم تسجيل دخولك من جهاز ثاني</h2>' +
        '<p class="pwa-p">الحساب مفتوح الحين على جهاز أو تطبيق ثاني، والموقع يعتمد آخر جهاز دخلت منه.<br>إذا تبي ترجع لهذا الجهاز اضغط الزر.</p>' +
        '<div class="pwa-btns"><button class="btn" onclick="location.reload()">استخدام هذا الجهاز</button></div></div>';
}
/* الأمن السيبراني وSSF ما لهم مسؤول أفراد | مسؤول الضباط لـ LSBD فقط */
function flHideSectorRole(sector, role, killNote) {
    try {
        var key = "openSectorPicker('" + sector + "','" + role + "')";
        var b = Array.prototype.filter.call(document.querySelectorAll('button'), function (x) { return (x.getAttribute('onclick') || '').indexOf(key) > -1; })[0];
        if (!b) return;
        var row = b.parentElement && b.parentElement.parentElement;
        if (!row) return;
        var note = row.nextElementSibling;
        if (killNote && note && /مسؤول الأفراد/.test(note.textContent || '')) note.remove();
        row.remove();
        var pk = document.getElementById('picker-' + sector + '-' + role); if (pk) pk.remove();
    } catch (e) {}
}
function flHideCyberPO() {
    flHideSectorRole('cyber', 'personnelOfficer', true);
    flHideSectorRole('ssf', 'personnelOfficer', false);
    flHideSectorRole('cyber', 'officersOfficer', false);
    flHideSectorRole('ssf', 'officersOfficer', true);
    flHideSectorRole('militaryAffairs', 'officersOfficer', false);
}
/* لوحة قائد القطاع: SSF بدون مسؤول أفراد | LSBD فيها مسؤول ضباط */
function flFixSectorPO() {
    try {
        var si = ME && ME.sectorInfo; if (!si) return;
        var pk = document.getElementById('po-picker'); var card = pk && pk.parentElement;
        if (!card) return;
        if (si.sector === 'ssf') { card.remove(); return; }
        if (si.sector !== 'lsbd') return;
        var c = document.createElement('div'); c.className = 'card'; c.id = 'oo-card';
        c.innerHTML = "<div class='row'><span>مسؤول الضباط: <b style='color:" + (si.officersOfficerName ? '#4ade80' : 'var(--muted)') + ";'>" + (si.officersOfficerName ? cyEsc(si.officersOfficerName) : 'غير معيّن') + "</b></span><div class='row' style='gap:6px;'><button class='btn sm gray' onclick='ooPicker()'>تعيين / تغيير</button>" + (si.officersOfficerName ? "<button class='btn danger sm' onclick='ooRemove()'>إزالة</button>" : '') + "</div></div><div style='color:var(--muted);font-size:12px;margin-top:6px;'>مسؤول الضباط يتحكم بالضباط من ملازم إلى فريق أول (ملاحظات وتحذيرات ومخالفاتهم) بنفس صلاحيات مسؤول الأفراد. طلبات الترقية والتنزيل تروح للقيادة العليا.</div><div id='oo-picker'></div>";
        card.parentElement.insertBefore(c, card.nextSibling);
    } catch (e) {}
}
var _flRSP = renderSectorPanel;
renderSectorPanel = function () { _flRSP.apply(this, arguments); flFixSectorPO(); };
async function ooPicker() {
    var el = document.getElementById('oo-picker'); if (!el) return;
    if (el.innerHTML.trim()) { el.innerHTML = ''; return; }
    el.innerHTML = 'جارِ التحميل...';
    try {
        var r = await api('/api/sector/members');
        var list = (r.list || []).filter(function (x) { return x.registeredName && MILITARY_RANKS.indexOf(x.rank) > MILITARY_RANKS.indexOf('رئيس رقباء'); });
        el.innerHTML = list.length ? list.map(function (x) {
            return "<div class='card' style='padding:8px 12px;margin-top:6px;'><div class='row'><span>" + cyEsc(x.registeredName) + " <span style='color:var(--muted);font-size:12px;'>(" + cyEsc(x.unit || '-') + " • " + cyEsc(x.rank) + ")</span></span><button class='btn sm' data-id='" + x.discord + "' onclick='ooAssign(this.dataset.id)'>تعيين</button></div></div>";
        }).join('') : "<p style='color:var(--muted);font-size:13px;'>لا يوجد ضباط بالقطاع</p>";
    } catch (e) { el.innerHTML = "<p style='color:#f87171;'>" + cyEsc(e.message) + "</p>"; }
}
async function ooAssign(id) {
    try { await api('/api/sector/officers-officer/assign', { method: 'POST', body: JSON.stringify({ discordId: id }) }); toast('تم التعيين'); await refreshMe(); renderSectorPanel(); } catch (e) { toast(e.message); }
}
async function ooRemove() {
    if (!(await confirmModal('تزيله من مسؤول الضباط؟'))) return;
    try { await api('/api/sector/officers-officer/remove', { method: 'POST', body: '{}' }); toast('تم'); await refreshMe(); renderSectorPanel(); } catch (e) { toast(e.message); }
}

/* ---------------- 🚗 الرتبة المخصصة للمركبة ---------------- */
var VR_ID = null;
